from pathlib import Path
import json,html
r=Path(__file__).resolve().parent.parent;items=json.loads((r/'evidence/shortlist.json').read_text());cards=[]
for x in items:
 pic=f'<img src="previews/{x["preview"]}.jpg" alt="{html.escape(x["alt"] or x["title"])}" style="object-position:{x["desktop"]}">'if x['preview']else'<div class="held">SCHEMATIC RETAINED<br>Permission / original required<br><small>Open the publisher reference below</small></div>'
 cards.append(f'<article id="{x["id"]}"><div class="picture" style="aspect-ratio:{"5/6"if x["id"]=="PH02"else"16/10"if x["id"]in["PH03","PH05","PH07"]else"4/3"}">{pic}</div><div class="copy"><p class="eyebrow">{x["id"]} / {html.escape(x["placement"])}</p><h2>{html.escape(x["title"])}</h2><p>{html.escape(x["owner"])}</p><p class="status">{x["license"]} · PENDING APPROVAL</p><p>{html.escape(x["assessment"])}</p><a href="{html.escape(x["source"])}">Original publisher / permission lead ↗</a></div></article>')
hero='''<section class="hero-study"><h2>Hero crop study — photograph only</h2><p>Existing navy overlay direction. This is a review study, not a homepage implementation. Mobile intentionally retains the cab/tracks, not the entire boom. Visible third-party branding remains an approval concern.</p><div class="hero-pair"><figure><div class="landscape"><img src="previews/hero-built.jpg" alt="Review photograph of a yellow excavator" style="object-position:70% 50%"><span class="overlay"></span><b>Left typography area</b></div><figcaption>Landscape proposal · 70% 50%</figcaption></figure><figure><div class="portrait"><img src="previews/hero-built.jpg" alt="Proposed narrow crop of the excavator" style="object-position:85% 50%"><span class="overlay"></span></div><figcaption>Narrow crop · 85% 50%</figcaption></figure></div></section>'''
(r/'REVIEW_BOARD.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Zieve photography shortlist — review only</title><style>*{box-sizing:border-box}body{margin:0;background:#f5f7f8;color:#0b2233;font-family:Georgia,serif;line-height:1.6}header,main{max-width:1280px;margin:auto;padding:32px 24px}header{border-top:4px solid #f2a21a}h1{font-size:clamp(32px,4vw,56px);line-height:1.1;max-width:900px}h2{font-size:22px;line-height:1.3}a{color:inherit;text-underline-offset:4px}a:focus-visible{outline:3px solid #c98210;outline-offset:4px}.notice{max-width:850px}.eyebrow,.status{font-size:12px;font-weight:bold;letter-spacing:.06em}.status{background:#0b2233;color:white;padding:8px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.grid article{background:white;border:1px solid #d5dde2;min-width:0}.picture{position:relative;background:#0b2233;overflow:hidden}.picture img{height:100%;width:100%;object-fit:cover;display:block}.copy{padding:20px;overflow-wrap:anywhere}.held{height:100%;display:grid;place-content:center;text-align:center;color:white;padding:24px}.held small{font-weight:normal}.hero-study{margin-bottom:48px}.hero-pair{display:grid;grid-template-columns:3fr 1fr;gap:24px;align-items:start}figure{margin:0}.landscape,.portrait{position:relative;overflow:hidden;background:#0b2233}.landscape{aspect-ratio:16/9}.portrait{aspect-ratio:9/16}.hero-pair img{height:100%;width:100%;object-fit:cover;display:block}.overlay{position:absolute;inset:0;background:linear-gradient(90deg,#0b2233,rgba(11,34,51,.85) 45%,rgba(11,34,51,.72) 72%,rgba(11,34,51,.4)),linear-gradient(0deg,#0b2233,transparent 50%)}b{position:absolute;color:white;left:8%;top:40%;max-width:50%;font-size:24px}figcaption{font-size:13px;margin-top:10px}@media(max-width:800px){.grid{grid-template-columns:1fr 1fr}}@media(max-width:500px){.grid{grid-template-columns:1fr}.hero-pair{grid-template-columns:1fr 1fr;gap:12px}.landscape{aspect-ratio:9/16}.hero-pair b{font-size:16px}header,main{padding:24px 20px}}</style><header><p class="eyebrow">PHASE 11A.5 / STAGE A</p><h1>Industrial photography selection</h1><p class="notice">Research and crop review only. No website photographs have been replaced. Nine candidates have verified free copyright-license terms, but none has production/brand approval. Two specialist placements remain permission leads. Stock scenes do not depict Zieve people, inventory, customers or facilities.</p><p><a href="IMAGE_SELECTION_REPORT.md">Selection report</a> · <a href="IMAGE_LICENSE_REGISTER.md">Rights register</a></p></header><main>'''+hero+'<section class="grid" aria-label="Eleven proposed placements">'+''.join(cards)+'</section></main></html>')
